def transform(grid):
    from collections import Counter
    if not grid:
        return grid

    # Count all colors
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1

    # Get sorted colors by frequency (ascending)
    sorted_colors = sorted(counts.items(), key=lambda x: x[1])

    # Most frequent (last) is background, least frequent (first) we'll map to target
    background = sorted_colors[-1][0]
    target_color = sorted_colors[0][0]

    # Transform: background → target, all others → 0
    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == background:
                new_row.append(target_color)
            else:
                new_row.append(0)
        result.append(new_row)

    return result
