    all_colors = set()
    for row in grid:
        for cell in row:
            all_colors.add(cell)
    if len(all_colors) < 2:
        return grid
    foreground = [c for c in all_colors if c != background][0]
    return [[foreground if cell == background else 0 for cell in row] for row in grid]
